type LeadRow = QuickViewLead & LeadTableRow & { categoryId: number; deliveredTimestamp: number; country: string };
type CreateForm = { categoryId: string; firstName: string; lastName: string; email: string; phone: string; city: string; postcode: string; metadata: Record<string, string> };
type StagedLeadAction = "" | "deliver" | "buyer" | "supplier" | "automation" | "chain" | "order" | "duplicate" | "deactivate" | "export" | "delete";
type LeadFilters = { categoryId: string; buyerId: string; supplierId: string; country: "" | "DE" | "AT" | "CH"; city: string; postcode: string; email: string; phone: string; createdFrom: string; createdTo: string; deliveredFrom: string; deliveredTo: string; minPrice: string; maxPrice: string; assignment: "alle" | "mit_kaeufer" | "ohne_kaeufer" | "mit_lieferant" | "ohne_lieferant"; deliveryResult: "" | "angeboten" | "angenommen" | "abgelehnt" | "übersprungen" };
type LeadSortMode = "created-desc" | "price-asc" | "price-desc" | "delivered-asc" | "delivered-desc";
/** Zeitraum der Leads-Tabelle: die festen Zeiträume (auch „Letzter Monat“), „Erstellt zwischen …“ (eigene Spanne), „Erstellt ab …“ (ab einem Tag) und „Erstellt vor …“ (vor einem Tag, ohne ihn) */
type LeadPeriod = DashboardPeriod | "since" | "before";
const OPEN_PERIODS: Array<LeadPeriod | ""> = ["custom", "since", "before"];
type SavedLeadView = { id: string; name: string; filters: LeadFilters; activePeriod: LeadPeriod | ""; sortMode: LeadSortMode };
const emptyForm: CreateForm = { categoryId: "", firstName: "", lastName: "", email: "", phone: "", city: "", postcode: "", metadata: {} };
const emptyLeadFilters: LeadFilters = { categoryId: "", buyerId: "", supplierId: "", country: "", city: "", postcode: "", email: "", phone: "", createdFrom: "", createdTo: "", deliveredFrom: "", deliveredTo: "", minPrice: "", maxPrice: "", assignment: "alle", deliveryResult: "" };
const asDateInput = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
/** Datum (JJJJ-MM-TT) um Tage verschieben – für „Erstellt vor …“: vor dem 24. = bis einschließlich 23. */
const shiftDay = (value: string, days: number) => { const date = new Date(`${value}T12:00:00`); date.setDate(date.getDate() + days); return asDateInput(date); };
const countryFlag = (country: string) => country === "AT" ? "🇦🇹" : country === "CH" ? "🇨🇭" : "🇩🇪";
/** Kurzes Datum für die Tabelle („20.11.26 19:15“) – ganz ausgeschrieben steht es im Hinweis der Zelle. */
const shortStamp = (value: Date | string | null | undefined) => value ? new Date(value).toLocaleString("de-DE", { day: "2-digit", month: "2-digit", year: "2-digit", hour: "2-digit", minute: "2-digit" }).replace(",", "") : "—";
const EXPORT_LIMIT = 5000;

function datePreset(preset: Exclude<DashboardPeriod, "custom">) {
  const range = dashboardRange(preset, "", "");
  return { from: asDateInput(range.from), to: asDateInput(range.until) };
}

function DynamicCategoryFields({ fields, values, onChange }: { fields: Array<{ id: number; label: string; fieldKey: string; fieldType: string; options: unknown; required: boolean }>; values: Record<string, string>; onChange: (fieldKey: string, value: string) => void }) {
  if (!fields.length) return null;
  return <section className="col-span-full mt-2 rounded-xl border border-violet-400/15 bg-violet-500/[.035] p-4"><div className="mb-3"><span className="eyebrow">KATEGORIE-FACHFELDER</span><h3 className="mt-1 text-sm font-semibold text-slate-100">Antworten für diese Lead-Kategorie</h3><p className="mt-1 text-xs text-slate-400">Pflichtfelder und Antwortkataloge werden direkt aus der gewählten Kategorie übernommen.</p></div><div className="grid gap-3 md:grid-cols-2">{fields.map((field) => { const options = Array.isArray(field.options) ? field.options.filter((item): item is string => typeof item === "string") : []; const label = `${field.label}${field.required ? " *" : ""}`; if (field.fieldType === "auswahl" || field.fieldType === "ja_nein") return <label key={field.id} className="text-xs text-slate-300">{label}<select className="filter-select mt-2 w-full" value={values[field.fieldKey] ?? ""} onChange={(event) => onChange(field.fieldKey, event.target.value)}><option value="">Antwort auswählen</option>{(field.fieldType === "ja_nein" ? ["Ja", "Nein"] : options).map((option) => <option key={option} value={option}>{option}</option>)}</select></label>; if (field.fieldType === "notiz") return <label key={field.id} className="text-xs text-slate-300 md:col-span-2">{label}<Textarea className="mt-2 min-h-24 bg-slate-950/40" value={values[field.fieldKey] ?? ""} onChange={(event) => onChange(field.fieldKey, event.target.value)} /></label>; return <label key={field.id} className="text-xs text-slate-300">{label}<Input className="mt-2" type={field.fieldType === "zahl" ? "number" : field.fieldType === "datum" ? "date" : "text"} value={values[field.fieldKey] ?? ""} onChange={(event) => onChange(field.fieldKey, event.target.value)} /></label>; })}</div></section>;
}

