; const [savedLeadViews, setSavedLeadViews] = useState<SavedLeadView[]>(() => { try { return JSON.parse(window.localStorage.getItem("tanesco-lead-saved-views") ?? "[]") as SavedLeadView[]; } catch { return []; } });
