  const leadListInput = useMemo(() => ({ status: statusMap[status], duplicatesOnly: status === "Dubletten", query: query || undefined, categoryId: Number(filters.categoryId) || undefined, buyerId: Number(filters.buyerId) || undefined, supplierId: Number(filters.supplierId) || undefined, country: filters.country || undefined, city: filters.city || undefined, postcode: filters.postcode || undefined, email: filters.email || undefined, phone: filters.phone || undefined, createdFrom: filters.createdFrom ? new Date(`${filters.createdFrom}T00:00:00`) : undefined, createdTo: filters.createdTo ? new Date(`${filters.createdTo}T23:59:59.999`) : undefined, deliveredFrom: filters.deliveredFrom ? new Date(`${filters.deliveredFrom}T00:00:00`) : undefined, deliveredTo: filters.deliveredTo ? new Date(`${filters.deliveredTo}T23:59:59.999`) : undefined, minPrice: filters.minPrice === "" ? undefined : Number(filters.minPrice), maxPrice: filters.maxPrice === "" ? undefined : Number(filters.maxPrice), assignment: filters.assignment, deliveryResult: filters.deliveryResult || undefined, page, pageSize }), [filterKey, filters, page, pageSize, query, status]);
